/**
 * Writes deploy/nginx-redirects.conf from LEGACY_REDIRECTS in seoData.js, so
 * the server-side 301s match the SPA's <Navigate> routes exactly.
 * Include it inside the site's `server {}` block (see deploy/nginx.conf).
 *
 *   npm run generate:redirects
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { LEGACY_REDIRECTS } from "../src/data/seoData.js";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const out = path.join(root, "deploy", "nginx-redirects.conf");

const lines = [
  "# Generated by scripts/generate-nginx-redirects.mjs from LEGACY_REDIRECTS",
  "# in src/data/seoData.js — do not edit by hand.",
  "",
];
for (const { from, to } of LEGACY_REDIRECTS) {
  if (from.includes(":slug")) {
    const prefix = from.replace("/:slug", "");
    const target = to.replace(":slug", "$1");
    lines.push(`location ~ ^${prefix}/([^/]+)/?$ { return 301 ${target}; }`);
  } else {
    lines.push(`location ~ ^${from}/?$ { return 301 ${to}; }`);
  }
}

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, `${lines.join("\n")}\n`);
console.log(`Wrote ${path.relative(root, out)} (${LEGACY_REDIRECTS.length} redirects)`);
